create table care_categories(id uuid primary key,family_id uuid not null references families(id),legacy_id text,category_type text,name text,icon text,active boolean not null default true,updated_at timestamptz not null default now(),deleted_at timestamptz);
create table diary_entries(id uuid primary key,family_id uuid not null references families(id),member_id uuid references health_members(id),legacy_id text,entry_date date,time_from text,time_to text,category text,title text,note text,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table appointments(id uuid primary key,family_id uuid not null references families(id),member_id uuid references health_members(id),type_id uuid,title text,appointment_date date,appointment_time text,time_to text,place text,doctor text,note text,status text,legacy_id text,legacy_type_id text,type_name text,person text,cost_text text,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table milestones(id uuid primary key,family_id uuid not null references families(id),member_id uuid references health_members(id),legacy_id text,milestone_key text,milestone_date date,title text,type text,category text,icon text,milestone_time text,description text,note text,photos jsonb default '[]',auto boolean default false,extra jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table monthly_notes(id uuid primary key,family_id uuid not null references families(id),month_index int not null,note text,updated_at timestamptz not null default now(),deleted_at timestamptz,unique(family_id,month_index));
do $$declare t text;begin foreach t in array array['care_categories','diary_entries','appointments','milestones','monthly_notes'] loop execute format('alter table %I enable row level security',t);execute format('create trigger updated before update on %I for each row execute function myb_set_updated_at()',t);end loop;end$$;
insert into care_categories(id,family_id,legacy_id,category_type,name,icon) values(myb_stable_uuid('cat:appointment'),myb_stable_uuid('family:main'),'at1','appointment_type','Khám','🏥'),(myb_stable_uuid('cat:diary'),myb_stable_uuid('family:main'),'dt1','diary_type','Kỷ niệm','📔');
create or replace function public.myb_app_shell_v1550(p_sync_id text default 'main') returns jsonb language plpgsql security definer set search_path=public as $$
declare v_diary jsonb;v_ms jsonb;v_appt jsonb;v_preg jsonb;v_app_members jsonb;v_monthly jsonb;v_appt_types jsonb;v_diary_types jsonb;v_cont jsonb;begin
 select coalesce(jsonb_agg(coalesce(de.extra,'{}')),'[]') into v_diary from diary_entries de where false;
 select coalesce(jsonb_agg(coalesce(ms.extra,'{}')),'[]') into v_ms from milestones ms where false;
 select coalesce(jsonb_agg(coalesce(ap.extra,'{}')),'[]') into v_appt from appointments ap where false;
 v_preg := '[]';
 select coalesce(jsonb_agg(coalesce(am.extra,'{}')),'[]') into v_app_members from health_members am where false;
 select coalesce(jsonb_object_agg(mn.month_index::text,mn.note),'{}') into v_monthly from monthly_notes mn where false;
 select coalesce(jsonb_agg(coalesce(cc.extra,'{}')),'[]') into v_appt_types from (select to_jsonb(x)||jsonb_build_object('id',legacy_id) extra from care_categories x where family_id=myb_stable_uuid('family:'||p_sync_id) and category_type='appointment_type' and deleted_at is null) cc;
 select coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('id',legacy_id)),'[]') into v_diary_types from care_categories x where family_id=myb_stable_uuid('family:'||p_sync_id) and category_type='diary_type' and deleted_at is null;
 select coalesce(jsonb_agg(extra||jsonb_build_object('id',legacy_id,'name',name,'kind',kind,'capacity',capacity_ml,'active',active)),'[]') into v_cont from milk_containers where family_id=myb_stable_uuid('family:'||p_sync_id);
 return jsonb_build_object('ok',true,'family_id',myb_stable_uuid('family:'||p_sync_id),'payload',jsonb_build_object('diary',v_diary,'milestones',v_ms,'appointments',v_appt,'monthlyNotes',v_monthly,'members',v_app_members,'appointmentTypes',v_appt_types,'diaryTypes',v_diary_types,'milkContainers',v_cont));end$$;
